import {labels,train,score,reason,xmp,zip} from './core.js';
const $=id=>document.getElementById(id),key='raw-curator-web-v1';let saved={feedback:{},rotations:{}};try{saved={...saved,...JSON.parse(localStorage.getItem(key)||'{}')};}catch{}let model=train(saved.feedback),photos=[],candidates=[],history=[],busy=false,cancelled=false,epoch=0,failed=[],workers=[];
function persist(){try{localStorage.setItem(key,JSON.stringify(saved));}catch{toast('浏览器存储不可用，本次反馈仍可导出。');}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500);}
function view(name){for(const id of ['intro','workspace','summary'])$(id).hidden=id!==name;}
function revoke(){for(const p of photos)URL.revokeObjectURL(p.url);}
const identity=f=>`${f.webkitRelativePath||f.name}|${f.size}|${f.lastModified}`;
async function choose(){if(busy){toast('请先停止当前分析。');return;}if('showDirectoryPicker'in window){try{const dir=await showDirectoryPicker({mode:'read'}),files=[];async function walk(handle,path=''){for await(const [name,entry]of handle.entries()){if(entry.kind==='directory')await walk(entry,path+name+'/');else{const f=await entry.getFile();Object.defineProperty(f,'webkitRelativePath',{value:path+name});files.push(f);}}}await walk(dir,dir.name+'/');await start(files,dir.name);return;}catch(e){if(e.name==='AbortError')return;toast('文件夹选择不可用，请使用浏览器文件选择器。');}}$('folderInput').click();}
$('choose').onclick=choose;$('change').onclick=choose;$('files').onclick=()=>{if(!busy)$('fileInput').click();};for(const id of ['folderInput','fileInput'])$(id).onchange=e=>{const files=[...e.target.files];e.target.value='';if(files.length)start(files,files[0].webkitRelativePath?.split('/')[0]||'已选择的照片');};
async function start(files,folder){if(busy)return;files=files.filter(f=>/\.(arw|jpe?g|png|webp|tiff?|dng|nef|cr2|raf|rw2)$/i.test(f.name));if(!files.length){toast('没有找到 ARW、JPEG、PNG 或其他支持的照片。');return;}revoke();photos=[];candidates=[];history=[];failed=[];busy=true;cancelled=false;const token=++epoch;view('workspace');$('folderName').textContent=folder.toUpperCase();$('heading').textContent='正在认识这些照片';$('cards').replaceChildren();$('empty').hidden=true;$('errors').hidden=true;$('progressPanel').hidden=false;$('progress').value=0;$('cancel').disabled=false;$('finish').disabled=true;$('change').disabled=true;let next=0,done=0;const count=Math.min(2,files.length);workers=Array.from({length:count},()=>new Worker('./worker.js',{type:'module'}));
 async function run(worker){while(next<files.length&&!cancelled&&token===epoch){const f=files[next++],id=identity(f);let result;try{result=await new Promise((resolve,reject)=>{worker.onmessage=e=>resolve(e.data);worker.onerror=e=>reject(Error(e.message||'照片处理线程失败'));worker.postMessage({id,file:f});});}catch(e){result={error:e.message};}if(token!==epoch)return;done++;if(result.error)failed.push({name:f.webkitRelativePath||f.name,error:result.error});else photos.push({id,name:f.name,path:f.webkitRelativePath||f.name,size:f.size,metrics:result.metrics,width:result.width,height:result.height,raw:result.raw,url:URL.createObjectURL(result.preview)});$('progress').value=done/files.length*100;$('status').textContent=`已分析 ${done} / ${files.length} 张 · 所有计算都在本机`;}}
 await Promise.all(workers.map(run));workers.forEach(w=>w.terminate());workers=[];busy=false;$('change').disabled=false;$('progressPanel').hidden=true;$('heading').textContent='这一轮，值得多看一眼';$('status').textContent=`${photos.length} 张可用${failed.length?' · '+failed.length+' 张未能处理':''}${cancelled?' · 已停止，可继续选片':''}`;$('finish').disabled=!photos.length;if(failed.length){$('errors').hidden=false;$('errorList').replaceChildren(...failed.map(f=>{const li=document.createElement('li');li.textContent=f.name+'：'+f.error;return li;}));}refresh();}
$('cancel').onclick=()=>{cancelled=true;$('cancel').disabled=true;$('status').textContent='正在完成当前照片，然后停止…';};
function roundRefresh(){const keeps=candidates.filter(id=>saved.feedback[id]?.choice==='keep');if(candidates.length&&keeps.length===candidates.length){candidates=[];toast(keeps.length===5?'本轮五张已保留，正在推荐下一轮。':'本轮已完成，继续下一轮。');}}
function refresh(){roundRefresh();const ids=new Set(photos.map(p=>p.id));candidates=candidates.filter(id=>ids.has(id)&&saved.feedback[id]?.choice!=='reject');const used=new Set(candidates);const pool=photos.filter(p=>!used.has(p.id)&&!saved.feedback[p.id]).sort((a,b)=>score(b.metrics,model)-score(a.metrics,model)||a.path.localeCompare(b.path));while(candidates.length<5&&pool.length)candidates.push(pool.shift().id);$('cards').replaceChildren(...candidates.map((id,i)=>card(photos.find(p=>p.id===id),i)));$('empty').hidden=!!candidates.length;$('undo').disabled=!history.length;const evaluated=photos.map(p=>saved.feedback[p.id]).filter(Boolean),kept=evaluated.filter(f=>f.choice==='keep').length;$('counts').textContent=`${kept} 张保留 · ${evaluated.length-kept} 张淘汰 · ${photos.length-evaluated.length} 张待选`;$('learning').textContent=model?`已从 ${model.count} 次反馈学习偏好`:'保留和淘汰各达到 2 张后开始学习';}
function radar(m){const values=[m[0],m[1],(m[2]+m[3])/2,m[4],m[6],m[8]],texts=['清晰度','曝光','剪裁保留','对比','色彩','构图代理'];const point=(r,i)=>[75+Math.sin(i*Math.PI/3)*r,75-Math.cos(i*Math.PI/3)*r];const poly=r=>values.map((v,i)=>point(r,i).join(',')).join(' ');const data=values.map((v,i)=>point(46*v/100,i).join(',')).join(' ');return `<svg viewBox="0 0 150 150" role="img" aria-label="${texts.map((t,i)=>t+' '+Math.round(values[i])).join('，')}">${[.33,.66,1].map(r=>`<polygon points="${poly(46*r)}"/>`).join('')}<polygon class="data" points="${data}"/>${texts.map((t,i)=>{const [x,y]=point(62,i);return `<text x="${x}" y="${y}" text-anchor="middle">${t}</text>`;}).join('')}</svg>`;}
function card(p,i){const el=document.createElement('article');el.className='card';const photo=document.createElement('div');photo.className='photo';const img=document.createElement('img');img.src=p.url;img.alt=p.name;img.loading='lazy';img.style.transform=`rotate(${saved.rotations[p.id]||0}deg)`;photo.append(img);const rank=document.createElement('span');rank.className='rank';rank.textContent=`TOP ${i+1} · ${score(p.metrics,model).toFixed(0)}`;photo.append(rank);const rot=document.createElement('button');rot.className='rotate';rot.textContent='↻';rot.title='顺时针旋转 90°（仅预览）';rot.setAttribute('aria-label','旋转 '+p.name);rot.onclick=e=>{e.stopPropagation();saved.rotations[p.id]=((saved.rotations[p.id]||0)+90)%360;persist();img.style.transform=`rotate(${saved.rotations[p.id]}deg)`;};photo.append(rot);photo.onclick=()=>{const image=$('lightbox').querySelector('img');image.src=p.url;image.style.transform=`rotate(${saved.rotations[p.id]||0}deg)`;$('lightbox').querySelector('p').textContent=p.path;$('lightbox').showModal();};el.append(photo);const body=document.createElement('div');body.className='card-body';const info=document.createElement('div');info.className='info';const title=document.createElement('h2');title.textContent=p.name;const why=document.createElement('p');why.textContent=reason(p.metrics);const meta=document.createElement('p');meta.className='meta';meta.textContent=`${p.width} × ${p.height} · ${(p.size/1024/1024).toFixed(1)} MB · ${p.raw?'RAW 内嵌预览':'图像像素分析'}`;const decisions=document.createElement('div');decisions.className='decisions';for(const [choice,label]of [['reject','淘汰'],['keep',saved.feedback[p.id]?.choice==='keep'?'✓ 已保留':'保留']]){const button=document.createElement('button');button.textContent=label;button.className=choice+(choice==='keep'&&saved.feedback[p.id]?.choice==='keep'?' active':'');button.disabled=choice==='keep'&&saved.feedback[p.id]?.choice==='keep';button.onclick=()=>decide(p,choice);decisions.append(button);}info.append(title,why,meta,decisions);const chart=document.createElement('div');chart.className='radar';chart.innerHTML=radar(p.metrics);body.append(info,chart);el.append(body);return el;}
function decide(p,choice){history.push({id:p.id,previous:saved.feedback[p.id],candidates:[...candidates]});saved.feedback[p.id]={choice,metrics:p.metrics,path:p.path,name:p.name,date:new Date().toISOString()};persist();model=train(saved.feedback);refresh();}
$('undo').onclick=()=>{const last=history.pop();if(!last)return;if(last.previous)saved.feedback[last.id]=last.previous;else delete saved.feedback[last.id];candidates=last.candidates;persist();model=train(saved.feedback);refresh();};
function finish(){if(busy)return;view('summary');const keeps=photos.filter(p=>saved.feedback[p.id]?.choice==='keep'),rejects=photos.filter(p=>saved.feedback[p.id]?.choice==='reject');$('summaryText').textContent=`${photos.length} 张照片中，你保留了 ${keeps.length} 张，淘汰了 ${rejects.length} 张。${photos.length-keeps.length-rejects.length} 张尚未评价。`;$('export').disabled=!keeps.length;$('keeps').replaceChildren(...keeps.map(p=>{const f=document.createElement('figure'),img=document.createElement('img'),caption=document.createElement('figcaption');img.src=p.url;img.alt=p.name;img.loading='lazy';caption.textContent=p.path;f.append(img,caption);return f;}));}
$('finish').onclick=finish;$('emptyFinish').onclick=finish;$('resume').onclick=()=>view('workspace');$('closeLightbox').onclick=()=>$('lightbox').close();
$('export').onclick=()=>{const keeps=photos.filter(p=>saved.feedback[p.id]?.choice==='keep'),entries=keeps.map(p=>['xmp/'+p.path.replace(/\.[^.]+$/,'.xmp'),xmp(p.name)]);entries.push(['kept-photos.txt',keeps.map(p=>p.path).join('\n')],['feedback.json',JSON.stringify({version:1,source:'browser-embedded-preview',generated:new Date().toISOString(),photos:photos.map(p=>({path:p.path,metrics:p.metrics,choice:saved.feedback[p.id]?.choice||'unreviewed'})),model},null,2)]);const url=URL.createObjectURL(zip(entries)),a=document.createElement('a');a.href=url;a.download='raw-photo-curator-selection.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);};
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
